// undefined's members: one function per member, each declared by the //kavun:member directive in its doc comment. The
// table, undefinedMethods, and the member entries of docs/reference/types/undefined.md (alphabetical, so the order here
// is free) are generated by cmd/kavun-gen — run `go generate ./...` after changing a directive or a doc comment.

// Render the value per the [format mini-language](../../format_mini_language.md).
//
// The universal render.
//
// ```go
// undefined.format()      // => "undefined"
// undefined.format("v")   // => "undefined"
// ```
//
//kavun:member format pure ([spec]) -> string
func undefinedFormat(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return FormatWithSpec(v, id, args)
}

// Report truthiness, which is always `false` for `undefined`.
//
// Always `false` — absence is never truthy.
//
// ```go
// undefined.is_true()   // => false
// ```
//
//kavun:member is_true pure () -> bool
func undefinedIsTrue(_ VM, v Value, _ member.ID, _ []Value) (Value, error) {
	t, err := ValueTypes[v.Type].IsTrue(v)
	if err != nil {
		return Undefined, err
	}
	return BoolValue(t), nil
}

// Answer the default — `undefined` has nothing to convert, so without one it raises.
//
// Every conversion member exists on `undefined`, each demanding a default — the full set is `bool` `byte`
// `rune` `int` `float` `decimal` `time` `date` `string` `runes` `bytes` `array` `dict` `record`. See
// [Absence and defaults](#absence-and-defaults) above.
//
// ```go
// undefined.int(0)        // => 0
// undefined.string("-")   // => "-"
// undefined.array([])     // => []
// undefined.int()         // Error: conversion: cannot convert undefined to int: value is missing
// ```
//
//kavun:member int pure ([default]) -> value
func undefinedInt(_ VM, _ Value, id member.ID, args []Value) (Value, error) {
	return undefinedConvert(id.String(), args)
}

